        while True:
            x=sock.recv(4096)
            if not x:break
            buf+=x
            while b'\r\n' in buf or b'\n' in buf:
                sep=b'\r\n' if b'\r\n' in buf else b'\n'; raw,buf=buf.split(sep,1); line=raw.decode(errors='replace')
                bits=line.split(' ',1); cmd=bits[0].upper(); rest=bits[1] if len(bits)>1 else ''
                args=rest.split()
                if cmd=='PASS':
                    token=rest.strip(); passed=bool(token_user(c,token))
                    if not passed:send(c,':huddle 464 * :Password incorrect')
